5: import { ActualizarCeremoniaRequest, AsignarEstudiantesCeremoniaRequest, AsignarEstudiantesCeremoniaResult, CrearCeremoniaRequest, CrearCeremoniaResult, EstudiantesProgramaCeremoniaResult, QuitarProgramaCeremoniaRequest, TableroCeremoniasResult } from '../models/ceremonia.model';
6: import { FirmanteActivo, SubirFirmaFirmanteRequest, SubirFirmaFirmanteResult } from '../models/firmante.model';
